```c  
#include <sys/syscall.h>  
#include <unistd.h>  
#include <fcntl.h>  
#include <stdio.h>  

int main() {  
    int pipefd[2];  
    pid_t pid;  
    char buffer[1024];  

    if (pipe(pipefd) == -1) {  
        return 1;  
    }  

    pid = fork();  
    if (pid == 0) {  
        close(pipefd[0]);  
        write(pipefd[1], "malicious_data", 15);  
        close(pipefd[1]);  
        return 0;  
    } else {  
        close(pipefd[1]);  
        read(pipefd[0], buffer, sizeof(buffer));  
        close(pipefd[0]);  
        return 0;  
    }  
}  
```  

